function processImage(imageElement) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  canvas.width = imageElement.width;
  canvas.height = imageElement.height;
  ctx.drawImage(imageElement, 0, 0);

  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

  const worker = new Worker('imageWorker.js');

  worker.onmessage = function(e) {
    ctx.putImageData(e.data.processedData, 0, 0);
    imageElement.src = canvas.toDataURL();
    worker.terminate();
  };

  worker.postMessage({ imageData, operation: 'grayscale' });
}

// dataWorker.js
self.onmessage = function(e) {
  const { data, operation } = e.data;

  try {
    const result = processData(data, operation);
    self.postMessage({ success: true, result });
  } catch (error) {
    self.postMessage({ success: false, error: error.message });
  }
};

function processData(data, operation) {
  switch (operation) {
    case 'filter':
      return data.filter(item => item.value > 100);
    case 'sort':
      return [...data].sort((a, b) => a.value - b.value);
    case 'aggregate':
      return data.reduce((sum, item) => sum + item.value, 0);
    default:
      throw new Error('Unknown operation');
  }
}

