function DataProcessorComponent() {
  const workerCode = `
    self.onmessage = function(e) {
      const data = e.data;
      const result = data.reduce((sum, num) => sum + num, 0);
      self.postMessage({ success: true, result });
    };
  `;

  const { result, isProcessing, execute } = useWorker(workerCode);

  const processData = () => {
    const largeArray = Array.from({ length: 1000000 }, (_, i) => i);
    execute(largeArray);
  };

  return (
    <div>
      <button onClick={processData} disabled={isProcessing}>
        {isProcessing ? 'Processing...' : 'Process Data'}
      </button>
      {result !== null && <div>Result: {result}</div>}
    </div>
  );
}

// Using transferables for large data
function processLargeArray(mainData) {
  const worker = new Worker('arrayWorker.js');

  worker.onmessage = function(e) {
    const processedData = e.data.result;
    console.log('Processed:', processedData.length);
    worker.terminate();
  };

  // Transfer array buffer (zero-copy)
  worker.postMessage(
    { data: mainData },
    [mainData.buffer] // Transfer ownership
  );

  // mainData is now empty (transferred to worker)
}

