class WorkerPool {
  constructor(workerScript, poolSize = navigator.hardwareConcurrency || 4) {
    this.workerScript = workerScript;
    this.poolSize = poolSize;
    this.workers = [];
    this.taskQueue = [];
    this.activeWorkers = 0;

    this.initialize();
  }

  initialize() {
    for (let i = 0; i < this.poolSize; i++) {
      const worker = new Worker(this.workerScript);
      worker.onmessage = this.handleWorkerMessage.bind(this);
      this.workers.push({ worker, busy: false });
    }
  }

  handleWorkerMessage(e) {
    const worker = this.workers.find(w => w.worker === e.target);
    if (worker) {
      worker.busy = false;
      this.activeWorkers--;

      // Resolve the task promise
      const task = this.taskQueue.find(t => t.worker === worker);
      if (task) {
        task.resolve(e.data);
        this.taskQueue = this.taskQueue.filter(t => t !== task);
      }

      this.processQueue();
    }
  }

  async execute(data) {
    return new Promise((resolve) => {
      this.taskQueue.push({ data, resolve, worker: null });
      this.processQueue();
    });
  }

  processQueue() {
    while (this.taskQueue.length > 0 && this.activeWorkers < this.poolSize) {
      const availableWorker = this.workers.find(w => !w.busy);
      if (availableWorker) {
        const task = this.taskQueue.shift();
        task.worker = availableWorker;
        availableWorker.busy = true;
        this.activeWorkers++;
        availableWorker.worker.postMessage(task.data);
      } else {
        break;
      }
    }
  }

  terminate() {
    this.workers.forEach(({ worker }) => worker.terminate());
    this.workers = [];
  }
}

// Usage
const pool = new WorkerPool('worker.js', 4);

const tasks = [1, 2, 3, 4, 5, 6, 7, 8].map(async (num) => {
  const result = await pool.execute({ num });
  console.log('Task', num, 'result:', result);
});

await Promise.all(tasks);
pool.terminate();
